  --shadow-lg: 0 10px 25px rgba(0,0,0,0.1);
  --shadow-xl: 0 20px 50px rgba(0,0,0,0.12);

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;

  --max-width: 1280px;
  --header-height: 80px;
}

/* Reset */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  line-height: 1.6;
  background: var(--color-white);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: 600;
  line-height: 1.2;
  color: var(--color-navy);
}

h1 { font-size: clamp(2.25rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.75rem); }
h4 { font-size: 1.25rem; }
h5 { font-size: 1.125rem; }

p {
  color: var(--color-text-light);
  line-height: 1.7;
}

/* Utility */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--spacing-lg);
}

@media (min-width: 768px) {
  .container { padding: 0 var(--spacing-2xl); }
}

.section-padding {
  padding: var(--spacing-3xl) 0;
}

@media (min-width: 768px) {
  .section-padding { padding: var(--spacing-5xl) 0; }
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-sm);
  padding: 0.75rem 1.75rem;
  font-family: var(--font-sans);
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  border: 2px solid transparent;
  cursor: pointer;
  transition: all var(--transition-base);
  white-space: nowrap;
  text-decoration: none;
}

.btn-primary {
  background: var(--color-primary);
  color: var(--color-white);
  border-color: var(--color-primary);
}

.btn-primary:hover {
  background: var(--color-primary-dark);
  border-color: var(--color-primary-dark);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background: transparent;
  color: var(--color-white);
  border-color: var(--color-white);
}

.btn-outline:hover {
  background: var(--color-white);
  color: var(--color-primary);
}

.btn-outline-dark {
  background: transparent;
  color: var(--color-primary);
  border-color: var(--color-primary);
}

.btn-outline-dark:hover {
  background: var(--color-primary);
  color: var(--color-white);
}

.btn-ghost {
  background: transparent;
  color: var(--color-primary);
  border: none;
  padding: 0.5rem 0;
  font-weight: 600;
}

.btn-ghost:hover {
  color: var(--color-primary-dark);
}

.btn-ghost svg,
.btn-ghost .arrow {
  transition: transform var(--transition-fast);
}

.btn-ghost:hover svg,
.btn-ghost:hover .arrow {
  transform: translateX(4px);
}

.btn-gold {
  background: var(--color-accent-gold);
  color: var(--color-white);
  border-color: var(--color-accent-gold);
}

.btn-gold:hover {
  background: #9A7209;
  border-color: #9A7209;
}

/* ========================================
   HEADER & NAVIGATION
   ======================================== */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: var(--color-white);
  border-bottom: 1px solid var(--color-border);
  height: var(--header-height);
  transition: background var(--transition-base), box-shadow var(--transition-base);
}

.site-header.scrolled {
  box-shadow: var(--shadow-md);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--spacing-lg);
}

.logo {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-primary);
  z-index: 1001;
}

.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--color-primary);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}

.logo-icon svg {
  width: 20px;
  height: 20px;
  color: var(--color-white);
}

/* Desktop Navigation */
.main-nav {
  display: none;
  align-items: center;
  gap: var(--spacing-xl);
  height: 100%;
}

@media (min-width: 1024px) {
  .main-nav { display: flex; }
}

.nav-item {
  position: relative;
  height: 100%;
  display: flex;
  align-items: center;
}

.nav-link {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-gray-700);
  transition: color var(--transition-fast);
  display: flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.5rem 0;
  position: relative;
}

.nav-link:hover,
.nav-link.active {
  color: var(--color-primary);
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--color-primary);
  transform: scaleX(0);
  transition: transform var(--transition-base);
}

.nav-link:hover::after,
.nav-link.active::after {
  transform: scaleX(1);
}

.nav-link .chevron {
  width: 14px;
  height: 14px;
  transition: transform var(--transition-fast);
}

.nav-item:hover .nav-link .chevron {
  transform: rotate(180deg);
}

/* Mega Menu */
.mega-menu {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  width: 720px;
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-top: 3px solid var(--color-primary);
  border-radius: 0 0 var(--radius-lg) var(--radius-lg);
  box-shadow: var(--shadow-xl);
  padding: var(--spacing-2xl);
  opacity: 0;
  visibility: hidden;
  transform: translateX(-50%) translateY(10px);
  transition: opacity var(--transition-base), visibility var(--transition-base), transform var(--transition-base);
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-2xl);
}

.nav-item:hover .mega-menu,
.mega-menu:hover {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(0);
}

.mega-menu-section h6 {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-gray-400);
  margin-bottom: var(--spacing-md);
}

.mega-menu-links {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-xs);
}

.mega-menu-links a {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-gray-700);
  padding: 0.4rem 0.75rem;
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}

.mega-menu-links a:hover {
  color: var(--color-primary);
  background: var(--color-gray-100);
}

/* Header Actions */
.header-actions {
  display: none;
  align-items: center;
  gap: var(--spacing-md);
}

@media (min-width: 1024px) {
  .header-actions { display: flex; }
}

.header-search {
  width: 36px;
  height: 36px;
  border: none;
  background: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-gray-600);
  border-radius: 50%;
  transition: background var(--transition-fast);
}

.header-search:hover {
  background: var(--color-gray-100);
}

/* Mobile Hamburger */
.hamburger {
  display: flex;
  flex-direction: column;
  gap: 5px;
  width: 28px;
  cursor: pointer;
  background: none;
  border: none;
  padding: 4px 0;
  z-index: 1001;
}

@media (min-width: 1024px) {
  .hamburger { display: none; }
}

.hamburger span {
  display: block;
  width: 100%;
  height: 2px;
  background: var(--color-navy);
  transition: all var(--transition-base);
  border-radius: 2px;
}

.hamburger.active span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}

.hamburger.active span:nth-child(2) {
  opacity: 0;
}

.hamburger.active span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

/* Mobile Navigation */
.mobile-nav {
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--color-white);
  z-index: 999;
  overflow-y: auto;
  transform: translateX(100%);
  transition: transform var(--transition-slow);
  padding: var(--spacing-xl) var(--spacing-lg);
}

.mobile-nav.active {
  transform: translateX(0);
}

.mobile-nav-item {
  border-bottom: 1px solid var(--color-border);
}

.mobile-nav-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-md) 0;
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--color-gray-700);
}

.mobile-nav-link .chevron {
  width: 18px;
  height: 18px;
  transition: transform var(--transition-base);
}

.mobile-nav-item.open .mobile-nav-link .chevron {
  transform: rotate(180deg);
}

.mobile-accordion {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}

.mobile-nav-item.open .mobile-accordion {
  max-height: 500px;
}

.mobile-accordion-content {
  padding: 0 0 var(--spacing-md) var(--spacing-md);
}

.mobile-accordion-content h6 {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-gray-400);
  margin-bottom: var(--spacing-sm);
  margin-top: var(--spacing-md);
}

.mobile-accordion-content a {
  display: block;
  padding: 0.4rem 0;
  font-size: 0.9375rem;
  color: var(--color-gray-600);
}

.mobile-accordion-content a:hover {
  color: var(--color-primary);
}

/* ========================================
   HERO SECTIONS
   ======================================== */
.hero {
  position: relative;
  min-height: 560px;
  display: flex;
  align-items: center;
  overflow: hidden;
  margin-top: var(--header-height);
}

.hero-bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(10,22,40,0.85) 0%, rgba(0,63,45,0.7) 100%);
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 680px;
  padding: var(--spacing-4xl) 0;
}

.hero-label {
  display: inline-block;
  font-family: var(--font-sans);
  font-size: 0.8125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--color-accent-teal);
  margin-bottom: var(--spacing-md);
}

.hero h1 {
  color: var(--color-white);
  margin-bottom: var(--spacing-lg);
}

.hero p {
  color: rgba(255,255,255,0.85);
  font-size: 1.125rem;
  margin-bottom: var(--spacing-xl);
  max-width: 560px;
}

.hero-subpage {
  min-height: 400px;
}

.hero-subpage .hero-content {
  padding: var(--spacing-3xl) 0;
}

/* ========================================
   FEATURED INSIGHTS
   ======================================== */
.featured-insights {
  background: var(--color-off-white);
}

.insights-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--spacing-xl);
}

@media (min-width: 768px) {
  .insights-grid { grid-template-columns: repeat(3, 1fr); }
}

.insight-card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.insight-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.insight-card-image {
  height: 200px;
  background-size: cover;
  background-position: center;
  position: relative;
}

.insight-card-tag {
  position: absolute;
  top: var(--spacing-md);
  left: var(--spacing-md);
  background: var(--color-primary);
  color: var(--color-white);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 0.75rem;
  border-radius: var(--radius-sm);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.insight-card-body {
  padding: var(--spacing-lg);
}

.insight-card-body h4 {
  font-family: var(--font-serif);
  font-size: 1.125rem;
  margin-bottom: var(--spacing-sm);
  color: var(--color-navy);
  line-height: 1.4;
}

.insight-card-body p {
  font-size: 0.875rem;
  color: var(--color-text-muted);
  margin-bottom: var(--spacing-md);
}

.insight-card-date {
  font-size: 0.8125rem;
  color: var(--color-gray-400);
}

/* ========================================
   ANNOUNCEMENT BANNER
   ======================================== */
.announcement-banner {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
  color: var(--color-white);
  padding: var(--spacing-xl) 0;
}

.announcement-inner {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
  align-items: flex-start;
}

@media (min-width: 768px) {
  .announcement-inner {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

.announcement-banner h3 {
  color: var(--color-white);
  font-size: 1.375rem;
}

/* ========================================
   ABOUT STATEMENT
   ======================================== */
.about-statement {
  background: var(--color-white);
}

.about-inner {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--spacing-3xl);
  align-items: center;
}

@media (min-width: 768px) {
  .about-inner { grid-template-columns: 1fr 1fr; }
}

.about-image {
  height: 400px;
  border-radius: var(--radius-lg);
  background-size: cover;
  background-position: center;
  box-shadow: var(--shadow-lg);
}

.about-text h2 {
  margin-bottom: var(--spacing-lg);
}

.about-text p {
  margin-bottom: var(--spacing-xl);
  font-size: 1.0625rem;
}

/* ========================================
   WHAT WE DO — TABBED SECTION
   ======================================== */
.what-we-do {
  background: var(--color-navy);
  color: var(--color-white);
  overflow: hidden;
}

.what-we-do h2 {
  color: var(--color-white);
  margin-bottom: var(--spacing-2xl);
}

.tabs-wrapper {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-xl);
}

@media (min-width: 768px) {
  .tabs-wrapper {
    flex-direction: row;
    gap: var(--spacing-3xl);
  }
}

.tabs-nav {
  display: flex;
  flex-direction: row;
  gap: var(--spacing-sm);
  overflow-x: auto;
}

@media (min-width: 768px) {
  .tabs-nav {
    flex-direction: column;
    gap: var(--spacing-md);
    min-width: 260px;
    flex-shrink: 0;
    border-right: 1px solid rgba(255,255,255,0.15);
    padding-right: var(--spacing-2xl);
    overflow-x: visible;
  }
}

.tab-btn {
  background: none;
  border: none;
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 500;
  color: rgba(255,255,255,0.5);
  cursor: pointer;
  text-align: left;
  padding: 0.75rem 1.25rem;
  border-radius: var(--radius-md);
  transition: all var(--transition-base);
  white-space: nowrap;
  position: relative;
}

@media (min-width: 768px) {
  .tab-btn {
    font-size: 1.125rem;
    white-space: normal;
  }
}

.tab-btn:hover {
  color: rgba(255,255,255,0.8);
  background: rgba(255,255,255,0.05);
}

.tab-btn.active {
  color: var(--color-white);
  background: rgba(255,255,255,0.1);
}

.tab-btn.active::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 3px;
  height: 60%;
  background: var(--color-accent-teal);
  border-radius: 3px;
  display: none;
}

@media (min-width: 768px) {
  .tab-btn.active::before { display: block; }
}

.tab-panel {
  display: none;
  animation: tabFadeIn 400ms ease forwards;
}

.tab-panel.active {
  display: block;
}

@keyframes tabFadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.tab-panel h3 {
  color: var(--color-white);
  margin-bottom: var(--spacing-md);
  font-size: 1.75rem;
}

.tab-panel p {
  color: rgba(255,255,255,0.75);
  font-size: 1.0625rem;
  margin-bottom: var(--spacing-lg);
  max-width: 540px;
}

.tab-panel .service-list {
  margin-bottom: var(--spacing-xl);
}

.tab-panel .service-list li {
  color: rgba(255,255,255,0.65);
  padding: 0.35rem 0;
  padding-left: 1.25rem;
  position: relative;
  font-size: 0.9375rem;
}

.tab-panel .service-list li::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 6px;
  height: 6px;
  background: var(--color-accent-teal);
  border-radius: 50%;
}

/* ========================================
   NEWSLETTER
   ======================================== */
.newsletter {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
  position: relative;
  overflow: hidden;
}

.newsletter::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -10%;
  width: 500px;
  height: 500px;
  border-radius: 50%;
  background: rgba(255,255,255,0.03);
}

.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--spacing-2xl);
  align-items: center;
  position: relative;
  z-index: 1;
}

@media (min-width: 768px) {
  .newsletter-inner { grid-template-columns: 1fr 1fr; }
}

.newsletter h2 {
  color: var(--color-white);
  margin-bottom: var(--spacing-md);
}

.newsletter p {
  color: rgba(255,255,255,0.8);
  font-size: 1.0625rem;
}

.newsletter-form {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}

@media (min-width: 480px) {
  .newsletter-form {
    flex-direction: row;
  }
}

.newsletter-form input {
  flex: 1;
  padding: 0.875rem 1.25rem;
  border: 2px solid rgba(255,255,255,0.2);
  border-radius: var(--radius-sm);
  background: rgba(255,255,255,0.1);
  color: var(--color-white);
  font-family: var(--font-sans);
  font-size: 0.9375rem;
  outline: none;
  transition: border-color var(--transition-fast);
}

.newsletter-form input::placeholder {
  color: rgba(255,255,255,0.5);
}

.newsletter-form input:focus {
  border-color: var(--color-accent-teal);
}

.newsletter-form button {
  padding: 0.875rem 2rem;
  background: var(--color-white);
  color: var(--color-primary);
  border: none;
  border-radius: var(--radius-sm);
  font-family: var(--font-sans);
  font-size: 0.9375rem;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition-base);
  white-space: nowrap;
}

.newsletter-form button:hover {
  background: var(--color-gray-100);
  transform: translateY(-1px);
}

/* ========================================
   LATEST INSIGHTS
   ======================================== */
.latest-insights {
  background: var(--color-off-white);
}

.latest-insights .section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: var(--spacing-2xl);
  flex-wrap: wrap;
  gap: var(--spacing-md);
}

.insights-list {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--spacing-xl);
}

@media (min-width: 768px) {
  .insights-list { grid-template-columns: repeat(3, 1fr); }
}

.insight-list-card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
}

.insight-list-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-lg);
}

.insight-list-image {
  height: 180px;
  background-size: cover;
  background-position: center;
}

.insight-list-body {
  padding: var(--spacing-lg);
}

.insight-list-meta {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  margin-bottom: var(--spacing-sm);
}

.insight-list-meta .tag {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--color-primary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.insight-list-meta .divider {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--color-gray-300);
}

.insight-list-meta .category {
  font-size: 0.75rem;
  color: var(--color-gray-500);
}

.insight-list-body h4 {
  font-size: 1.0625rem;
  line-height: 1.4;
  margin-bottom: var(--spacing-sm);
}

.insight-list-body .date {
  font-size: 0.8125rem;
  color: var(--color-gray-400);
}

/* ========================================
   OUR COMMITMENT
   ======================================== */
.commitment {
  background: var(--color-white);
}

.commitment h2 {
  text-align: center;
  margin-bottom: var(--spacing-2xl);
}

.commitment-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--spacing-xl);
}

@media (min-width: 768px) {
  .commitment-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .commitment-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.commitment-card {
  text-align: center;
  padding: var(--spacing-xl);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  transition: all var(--transition-base);
}

.commitment-card:hover {
  border-color: var(--color-primary);
  box-shadow: var(--shadow-md);
}

.commitment-icon {
  width: 56px;
  height: 56px;
  margin: 0 auto var(--spacing-md);
  background: var(--color-gray-100);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-primary);
}

.commitment-card h4 {
  margin-bottom: var(--spacing-sm);
  font-family: var(--font-serif);
}

.commitment-card p {
  font-size: 0.875rem;
  margin-bottom: var(--spacing-md);
  line-height: 1.6;
}

/* ========================================
   FOOTER
   ======================================== */
.site-footer {
  background: var(--color-navy);
  color: var(--color-white);
  padding: var(--spacing-4xl) 0 var(--spacing-xl);
}

.footer-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--spacing-2xl);
  margin-bottom: var(--spacing-3xl);
}

@media (min-width: 768px) {
  .footer-grid {
    grid-template-columns: 2fr 1fr 1fr 1fr;
  }
}

.footer-brand .logo {
  color: var(--color-white);
  margin-bottom: var(--spacing-md);
}

.footer-brand .logo .logo-icon {
  background: rgba(255,255,255,0.15);
}

.footer-brand p {
  color: rgba(255,255,255,0.6);
  font-size: 0.875rem;
  max-width: 300px;
}

.footer-col h5 {
  font-family: var(--font-sans);
  font-weight: 600;
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: rgba(255,255,255,0.4);
  margin-bottom: var(--spacing-md);
}

.footer-col a {
  display: block;
  color: rgba(255,255,255,0.7);
  font-size: 0.9375rem;
  padding: 0.3rem 0;
  transition: color var(--transition-fast);
}

.footer-col a:hover {
  color: var(--color-white);
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: var(--spacing-xl);
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
  align-items: center;
}

@media (min-width: 768px) {
  .footer-bottom {
    flex-direction: row;
    justify-content: space-between;
  }
}

.footer-bottom p {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.4);
}

.footer-legal {
  display: flex;
  gap: var(--spacing-lg);
  flex-wrap: wrap;
}

.footer-legal a {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.4);
  transition: color var(--transition-fast);
}

.footer-legal a:hover {
  color: rgba(255,255,255,0.8);
}

/* ========================================
   SERVICES PAGE
   ======================================== */
.services-intro {
  text-align: center;
  max-width: 720px;
  margin: 0 auto;
}

.services-intro h2 {
  margin-bottom: var(--spacing-md);
}

.services-intro p {
  font-size: 1.0625rem;
}

.services-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--spacing-xl);
}

@media (min-width: 768px) {
  .services-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .services-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.service-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--spacing-2xl);
  transition: all var(--transition-base);
  display: flex;
  flex-direction: column;
}

.service-card:hover {
  border-color: var(--color-primary);
  box-shadow: var(--shadow-lg);
  transform: translateY(-3px);
}

.service-card-icon {
  width: 48px;
  height: 48px;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-white);
  margin-bottom: var(--spacing-lg);
}

.service-card h3 {
  font-size: 1.25rem;
  margin-bottom: var(--spacing-md);
}

.service-card p {
  font-size: 0.9375rem;
  margin-bottom: var(--spacing-lg);
  flex: 1;
}

.service-card .btn-ghost {
  align-self: flex-start;
}

/* ========================================
   CAPABILITIES GRID
   ======================================== */
.capabilities-section {
  background: var(--color-off-white);
}

.capabilities-section h2 {
  text-align: center;
  margin-bottom: var(--spacing-md);
}

.capabilities-section > .container > p {
  text-align: center;
  max-width: 640px;
  margin: 0 auto var(--spacing-2xl);
}

.capabilities-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--spacing-xl);
}

@media (min-width: 768px) {
  .capabilities-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .capabilities-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.capability-card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: var(--spacing-xl);
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
  border-left: 4px solid transparent;
}

.capability-card:hover {
  box-shadow: var(--shadow-lg);
  border-left-color: var(--color-primary);
  transform: translateY(-2px);
}

.capability-card h4 {
  font-family: var(--font-serif);
  margin-bottom: var(--spacing-sm);
  color: var(--color-navy);
}

.capability-card p {
  font-size: 0.9rem;
  line-height: 1.6;
}

/* ========================================
   FEATURED TOPICS
   ======================================== */
.featured-topics {
  background: var(--color-white);
}

.topics-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--spacing-md);
}

@media (min-width: 768px) {
  .topics-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .topics-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.topic-card {
  padding: var(--spacing-xl);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
