  cursor: pointer;
}

.topic-card:hover {
  border-color: var(--color-primary);
  background: var(--color-gray-100);
}

.topic-card-icon {
  width: 48px;
  height: 48px;
  margin: 0 auto var(--spacing-md);
  background: var(--color-gray-100);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-primary);
}

.topic-card:hover .topic-card-icon {
  background: var(--color-primary);
  color: var(--color-white);
}

.topic-card h4 {
  font-size: 1rem;
}

/* ========================================
   TESTIMONIAL
   ======================================== */
.testimonial-section {
  background: var(--color-navy);
  color: var(--color-white);
}

.testimonial-inner {
  max-width: 720px;
  margin: 0 auto;
  text-align: center;
}

.testimonial-quote {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 2.5vw, 1.75rem);
  color: var(--color-white);
  line-height: 1.5;
  margin-bottom: var(--spacing-xl);
  font-style: italic;
}

.testimonial-quote::before {
  content: '\201C';
  font-size: 3rem;
  color: var(--color-accent-teal);
  display: block;
  margin-bottom: var(--spacing-sm);
  line-height: 1;
}

.testimonial-author {
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.7);
}

.testimonial-author strong {
  color: var(--color-white);
}

/* ========================================
   DEAL FLOW CTA
   ======================================== */
.deal-flow-cta {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
  text-align: center;
}

.deal-flow-cta h2 {
  color: var(--color-white);
  margin-bottom: var(--spacing-md);
}

.deal-flow-cta p {
  color: rgba(255,255,255,0.8);
  max-width: 560px;
  margin: 0 auto var(--spacing-xl);
  font-size: 1.0625rem;
}

/* ========================================
   PROPERTY TYPES CTA
   ======================================== */
.property-types {
  background: var(--color-off-white);
}

.property-types h2 {
  text-align: center;
  margin-bottom: var(--spacing-2xl);
}

.property-types-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--spacing-md);
}

@media (min-width: 768px) {
  .property-types-grid {
    grid-template-columns: repeat(5, 1fr);
  }
}

.property-type-card {
  text-align: center;
  padding: var(--spacing-xl) var(--spacing-md);
  background: var(--color-white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border);
  transition: all var(--transition-base);
  cursor: pointer;
}

.property-type-card:hover {
  border-color: var(--color-primary);
  box-shadow: var(--shadow-md);
}

.property-type-icon {
  width: 48px;
  height: 48px;
  margin: 0 auto var(--spacing-md);
  color: var(--color-primary);
}

.property-type-card h5 {
  font-family: var(--font-sans);
  font-weight: 600;
  font-size: 0.9375rem;
}

/* ========================================
   RELATED SERVICES
   ======================================== */
.related-services {
  background: var(--color-white);
}

.related-services h2 {
  text-align: center;
  margin-bottom: var(--spacing-2xl);
}

.related-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--spacing-lg);
}

@media (min-width: 768px) {
  .related-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.related-card {
  display: flex;
  align-items: center;
  gap: var(--spacing-lg);
  padding: var(--spacing-lg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  transition: all var(--transition-base);
}

.related-card:hover {
  border-color: var(--color-primary);
  box-shadow: var(--shadow-md);
}

.related-card-icon {
  width: 48px;
  height: 48px;
  min-width: 48px;
  background: var(--color-gray-100);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-primary);
}

.related-card h4 {
  font-size: 1rem;
  margin-bottom: 0.25rem;
}

.related-card p {
  font-size: 0.8125rem;
}

/* ========================================
   PARTNER CAROUSEL
   ======================================== */
.partners-section {
  background: var(--color-white);
}

.carousel-wrapper {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform var(--transition-slow);
}

.carousel-slide {
  min-width: 100%;
  padding: var(--spacing-xl);
}

.carousel-slide-inner {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--spacing-xl);
  align-items: center;
  background: var(--color-off-white);
  border-radius: var(--radius-lg);
  padding: var(--spacing-2xl);
}

@media (min-width: 768px) {
  .carousel-slide-inner {
    grid-template-columns: 1fr 1fr;
  }
}

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: var(--spacing-md);
  margin-top: var(--spacing-xl);
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border: 2px solid var(--color-border);
  border-radius: 50%;
  background: var(--color-white);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-gray-600);
  transition: all var(--transition-fast);
}

.carousel-btn:hover {
  border-color: var(--color-primary);
  color: var(--color-primary);
}

.carousel-dots {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-gray-300);
  border: none;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.carousel-dot.active {
  background: var(--color-primary);
  width: 24px;
