.deal-flow-cta h2 {
  color: var(--color-white);
  margin-bottom: var(--spacing-md);
}

.deal-flow-cta p {
  color: rgba(255,255,255,0.8);
  max-width: 560px;
  margin: 0 auto var(--spacing-xl);
  font-size: 1.0625rem;
}

