}

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: var(--spacing-md);
  margin-top: var(--spacing-xl);
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border: 2px solid var(--color-border);
  border-radius: 50%;
