  align-items: center;
  justify-content: center;
  color: var(--color-gray-600);
  transition: all var(--transition-fast);
}

.carousel-btn:hover {
  border-color: var(--color-primary);
  color: var(--color-primary);
}

.carousel-dots {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-gray-300);
  border: none;
  cursor: pointer;
  transition: all var(--transition-fast);
}

