.stat-number {
  font-family: var(--font-serif);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-accent-teal);
  line-height: 1;
  margin-bottom: var(--spacing-xs);
}

.stat-label {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.6);
}

.partnership-highlight h2 {
  color: var(--color-white);
  margin-bottom: var(--spacing-md);
}

.partnership-highlight p {
  color: rgba(255,255,255,0.75);
  font-size: 1.0625rem;
}

/* ========================================
   BREADCRUMB
   ======================================== */
.breadcrumb {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  margin-bottom: var(--spacing-md);
}

.breadcrumb a {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.6);
  transition: color var(--transition-fast);
}

.breadcrumb a:hover {
  color: var(--color-white);
}

.breadcrumb .separator {
  color: rgba(255,255,255,0.4);
  font-size: 0.75rem;
}

.breadcrumb .current {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.9);
  font-weight: 500;
}

/* ========================================
   ANIMATIONS
   ======================================== */
.fade-in {
  opacity: 0;
